<?php
declare(strict_types=1);
$isVendor=($ownerType??'admin')==='vendor';
$weekdays=[1=>'Pzt',2=>'Sal',3=>'Çar',4=>'Per',5=>'Cum',6=>'Cmt',7=>'Paz'];
$maskDays=static function(int $mask):array{$days=[];for($day=1;$day<=7;$day++){if(($mask&(1<<($day-1)))!==0)$days[]=$day;}return $days;};
?>
